protected function sanitizeReturnUrl(string $url, string $base): Uri
{
    if (empty($url)) {
        return new Uri($base);
    }

    try {
        $parsedUrl = new Uri($url);
    } catch (\InvalidArgumentException $e) {
        return new Uri($base);
    }

    if (in_array($parsedUrl->getHost(), $this->getAllowedRedirectDomains())) {
        return $parsedUrl;
    }

    return new Uri($base);
}
